// Category A — React Aria owns the color area behavior and inline gradient/position.
import {
  ColorArea as AriaColorArea,
  ColorThumb,
} from "react-aria-components";
import type { ColorAreaProps as AriaColorAreaProps } from "react-aria-components";
import type { Ref } from "react";
import "./ColorArea.css";

// NO `description`: React Aria's ColorArea root IS the painted gradient (the wrapper sets its
// width/height), so helper text rendered inside draws ON the colour (white text over red). Giving it somewhere to go means adding a wrapper element around a Category-A
// component for a prop nothing has asked for. `ColorWheel` keeps one because its root is not the
// painted box; `ColorSlider` keeps one and gained the visible label that makes it describable.
export interface ColorAreaProps extends Omit<AriaColorAreaProps, "className" | "children"> {
  /** Additional class. sd-color-area is always preserved. */
  className?: string;
  /** Passed to the underlying area DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ColorArea({ className, ref, ...props }: ColorAreaProps) {
  return (
    <AriaColorArea
      {...props}
      ref={ref}
      className={className ? `sd-color-area ${className}` : "sd-color-area"}
    >
      <ColorThumb className="sd-color-area__thumb" />
    </AriaColorArea>
  );
}

.sd-color-area {
  width: var(--sd-color-area-size);
  height: var(--sd-color-area-size);
  border-radius: var(--sd-color-area-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  flex-shrink: 0;
  forced-color-adjust: none;
}
.sd-color-area[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-color-area__thumb {
  width: var(--sd-color-area-thumb-size);
  height: var(--sd-color-area-thumb-size);
  border: var(--sd-color-area-thumb-border-width) solid var(--sd-color-area-thumb-border);
  border-radius: var(--sd-color-area-thumb-radius);
  corner-shape: round;
  box-shadow: var(--sd-color-area-thumb-shadow);
  box-sizing: border-box;
}
/* Hover/drag feedback halo (RAC's ColorThumb emits data-hovered/data-dragging), composed
   over the base contrast ring — mirrors Slider's thumb affordance. */
.sd-color-area__thumb[data-hovered] {
  box-shadow: var(--sd-color-area-thumb-shadow-hover);
}
.sd-color-area__thumb[data-dragging] {
  box-shadow: var(--sd-color-area-thumb-shadow-dragging);
}
.sd-color-area__thumb[data-focus-visible] {
  width: var(--sd-color-area-thumb-size-focused);
  height: var(--sd-color-area-thumb-size-focused);
}
